mapper.select:
SELECT m.business_id AS id, m.conversation_id, c.session_id, m.status
FROM project_message m JOIN project_conversation c
ON c.business_id = m.conversation_id
WHERE m.tenant_id = #{tenantId} AND m.project_id = #{projectId}
AND m.conversation_id = #{conversationId}
AND m.client_message_id = #{clientMessageId} LIMIT 1

mapper.update:
UPDATE conversation_event_sequence SET next_sequence = #{newNext}
WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId}
AND next_sequence = #{next}

mapper.select:
SELECT business_id AS id, project_id, conversation_id, message_id, sequence,
event_type, payload, created_at FROM project_event
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND visibility = 'PUBLIC' AND conversation_id = #{conversationId}
AND sequence > #{afterSequence} ORDER BY sequence LIMIT #{limit}

SELECT message_text FROM project_message
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND conversation_id = #{conversationId}
ORDER BY created_at DESC LIMIT #{limit}
